<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import * as T from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';import {GLTFExporter} from 'three/addons/exporters/GLTFExporter.js';
import {loadDuck} from './DuckAssetLoader';import {DuckController} from './DuckController';import {DuckStateMachine} from './DuckStateMachine';import {PondScene} from './PondScene';import {WaterEffects} from './WaterEffects';import {DuckInteraction} from './DuckInteraction';import {loadPet,savePet} from './DuckPetState';import {DuckAudio} from './DuckAudio';import {REGION_NAMES,DEFAULT_PALETTE,loadPaint,storePaint} from './DuckPaint';
const saved=loadPet(),name=ref(saved.name),waterline=ref(saved.waterline),yaw=ref(saved.yaw),host=ref<HTMLDivElement>(),mode=ref('painted'),petMode=ref(false),sound=ref(false),error=ref(''),ready=ref(false),status=ref('idle'),message=ref('正在加载 STL 几何与候选分区…'),mood=ref(Math.round(saved.mood)),energy=ref(Math.round(saved.energy)),fps=ref(0),loadMs=ref(0),meta=ref<any>(null),details=ref(false);
const editing=ref(true),tool=ref('select'),selected=ref(0),palette=ref([...DEFAULT_PALETTE]),hex=ref(DEFAULT_PALETTE[0]),highlight=ref(false),radius=ref(2.5),saveStatus=ref('本地自动保存'),undoCount=ref(0),exporting=ref(false),regions=REGION_NAMES;
const labels:Record<string,string>={idle:'自在漂浮',swim:'慢慢游动',react:'回应你',pet:'享受抚摸',celebrate:'开心一下',sleep:'睡个好觉'};
const machine=new DuckStateMachine();Object.assign(machine,{mood:saved.mood,energy:saved.energy});
let renderer:T.WebGLRenderer,pond:PondScene,duck:DuckController,effects:WaterEffects,camera:T.PerspectiveCamera,controls:OrbitControls,interaction:DuckInteraction,resize:ResizeObserver,raf=0,abort=new AbortController(),audio=new DuckAudio(),last=0,frames=0,windowStart=0,lastUI=0,lastSave=0,disposed=false,geometryKey='',saveTimer:any;
const persist=()=>savePet({name:name.value,mood:machine.mood,energy:machine.energy,waterline:waterline.value,yaw:yaw.value});
async function saveColors(){if(!duck)return;clearTimeout(saveTimer);saveStatus.value='正在保存…';try{await storePaint(geometryKey,duck.paint.snapshot());saveStatus.value='已保存在本机';}catch{saveStatus.value='本机保存失败，请导出配置备份';}}
function scheduleSave(){saveStatus.value='有修改，等待保存';clearTimeout(saveTimer);saveTimer=setTimeout(saveColors,350);}
function setColor(c:string){if(!/^#[0-9a-f]{6}$/i.test(c)){saveStatus.value='请输入 #RRGGBB 六位颜色';return;}hex.value=c;palette.value[selected.value]=c;duck.paint.palette=[...palette.value];duck.paint.refresh();scheduleSave();}
function onHexInput(e:Event){const v=(e.target as HTMLInputElement).value;if(/^#[0-9a-f]{6}$/i.test(v))setColor(v);}
function preset(kind:string){const p=[...DEFAULT_PALETTE];if(kind==='pink')for(const i of [0,1,4,5,6])p[i]='#f0bed0';if(kind==='white')for(const i of [0,1,4,5,6])p[i]='#f3f1e7';palette.value=p;duck.paint.palette=[...p];hex.value=p[selected.value];duck.paint.refresh();scheduleSave();}
function syncInput(){if(!interaction)return;interaction.petMode=petMode.value&&!editing.value;interaction.paintMode=editing.value?(tool.value==='brush'?'brush':'select'):'off';controls.enabled=!petMode.value;controls.mouseButtons.LEFT=editing.value&&tool.value==='brush'?-1:T.MOUSE.ROTATE;controls.mouseButtons.RIGHT=T.MOUSE.ROTATE;duck.paint.highlight=highlight.value&&editing.value;duck.paint.selected=selected.value;duck.paint.refresh();}
function act(s:string,p?:any){if(!ready.value)return;
 if(s==='paint:select'){selected.value=duck.paint.labels[p.face];message.value='已选中'+regions[selected.value]+'，修改颜色即可整区应用';return;}
 if(s==='paint:start'){duck.paint.begin();return;}
 if(s==='paint:move'){const n=duck.paint.brush(p.face,radius.value,selected.value);if(n)message.value='将表面划入「'+regions[selected.value]+'」分区';return;}
 if(s==='paint:end'){duck.paint.commit();undoCount.value=duck.paint.history.length;scheduleSave();return;}
 if(editing.value)return;if(s==='react'&&machine.state==='sleep')s='wake';const accepted=machine.request(s,p);if(accepted)void audio.chirp();message.value=accepted&&s==='react'&&p?.face!=null?'碰到了'+duck.partAt(p.face)+'附近。嘎！':machine.reason;status.value=machine.state;
}
function undo(){if(duck.paint.undo()){undoCount.value=duck.paint.history.length;scheduleSave();message.value='已撤销一次分区修正';}}
function resetRegions(){duck.paint.resetRegions();undoCount.value=duck.paint.history.length;scheduleSave();message.value='已恢复候选分区，可撤销';}
function resetView(){camera.position.set(...(editing.value?[4.4,4.7,6.8]:[6.5,6.7,9]) as [number,number,number]);controls.target.set(0,.65,0);controls.update();}
function download(b:Blob,file:string){const a=document.createElement('a'),url=URL.createObjectURL(b);a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportGLB(){exporting.value=true;const g=duck.paint.exportGeometry(),m=new T.MeshStandardMaterial({vertexColors:true,roughness:.68,side:T.DoubleSide}),obj=new T.Mesh(g,m);obj.name='scanned_duck_custom_color';obj.userData={source:meta.value.source_scan,geometryKey,units:'meters',color:'user-assigned regions, not measured RGB'};try{const result=await new GLTFExporter().parseAsync(obj,{binary:true});download(new Blob([result as ArrayBuffer],{type:'model/gltf-binary'}),'duck-custom-color.glb');message.value='彩色 GLB 已导出，保留模型外形与自选颜色';}catch(e:any){message.value='导出失败：'+e.message;}finally{g.dispose();m.dispose();exporting.value=false;}}
function exportConfig(){download(new Blob([JSON.stringify({version:1,geometryKey,palette:palette.value,labels:Array.from(duck.paint.labels)})],{type:'application/json'}),'duck-color-regions.json');}
async function importConfig(e:Event){const input=e.target as HTMLInputElement;try{const file=input.files?.[0];if(!file)return;if(file.size>2000000)throw Error('配置文件过大');const data=JSON.parse(await file.text());if(data.geometryKey!==geometryKey||!Array.isArray(data.labels)||data.labels.length!==duck.paint.labels.length||!data.labels.every((v:any)=>Number.isInteger(v)&&v>=0&&v<8)||!Array.isArray(data.palette)||data.palette.length!==8||!data.palette.every((v:any)=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v)))throw Error('配置与当前几何不匹配或数据无效');duck.paint.begin();duck.paint.restore({labels:Uint8Array.from(data.labels),palette:data.palette});duck.paint.changed=true;duck.paint.commit();palette.value=[...duck.paint.palette];hex.value=palette.value[selected.value];undoCount.value=duck.paint.history.length;scheduleSave();message.value='分区与颜色配置已恢复';}catch(e:any){message.value='导入失败：'+e.message;}input.value='';}
watch(mode,v=>duck?.mode(v));watch([petMode,tool,highlight],syncInput);watch(selected,v=>{hex.value=palette.value[v];syncInput();});watch(editing,v=>{if(!ready.value)return;petMode.value=false;machine.request('stop');if(v){machine.x=0;machine.z=0;machine.yaw=0;}syncInput();resetView();message.value=v?'点击模型选区，或选择右侧部位，再设置颜色':'点击水面游动；点击小鸭回应';});watch(sound,v=>{audio.enabled=v;if(v)void audio.chirp();});watch([waterline,yaw],persist);watch(name,persist);
async function start(){try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;host.value!.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','STL 上色与鸭子互动视图');pond=new PondScene();camera=new T.PerspectiveCamera(38,1,.1,60);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=4.2;controls.maxDistance=16;controls.minPolarAngle=.35;controls.maxPolarAngle=1.35;resetView();resize=new ResizeObserver(()=>{if(!host.value)return;const w=host.value.clientWidth,h=host.value.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();});resize.observe(host.value!);
 const data=await loadDuck(abort.signal);if(disposed){data.meshGeometry.dispose();return;}meta.value=data.meta;loadMs.value=Math.round(data.loadMs);geometryKey=data.seg.geometry_key;duck=new DuckController(data);try{const savedColors=await loadPaint(geometryKey);if(savedColors){duck.paint.restore(savedColors);palette.value=[...duck.paint.palette];hex.value=palette.value[selected.value];saveStatus.value='已恢复本机上色';}}catch{saveStatus.value='本机保存不可用，请导出配置';}if(disposed){duck.dispose();return;}pond.scene.add(duck.root);effects=new WaterEffects();pond.scene.add(effects.group);interaction=new DuckInteraction(renderer.domElement,camera,duck.root,pond.water,act);ready.value=true;syncInput();message.value='点击模型选区，或选择右侧部位，再设置颜色';last=performance.now();windowStart=last;
 const tick=(now:number)=>{if(disposed)return;raf=requestAnimationFrame(tick);const dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;if(!editing.value)machine.update(dt);duck.waterline=waterline.value;duck.yawOffset=yaw.value;duck.update(machine);pond.update(machine,dt);for(const e of machine.events.splice(0))effects.emit(e.type,e.x,e.z);effects.update(dt,camera);controls.update();renderer.render(pond.scene,camera);frames++;if(now-windowStart>1000){fps.value=Math.round(frames*1000/(now-windowStart));frames=0;windowStart=now;}if(now-lastUI>150){lastUI=now;status.value=machine.state;mood.value=Math.round(machine.mood);energy.value=Math.round(machine.energy);}if(now-lastSave>5000){lastSave=now;persist();}};raf=requestAnimationFrame(tick);
 }catch(e:any){if(e.name!=='AbortError')error.value='模型或画布加载失败：'+e.message;}}
function retry(){location.reload();}
function visibility(){last=performance.now();windowStart=last;frames=0;}
onMounted(()=>{void start();document.addEventListener('visibilitychange',visibility);window.addEventListener('beforeunload',persist);});
onBeforeUnmount(()=>{disposed=true;abort.abort();cancelAnimationFrame(raf);clearTimeout(saveTimer);if(duck)void saveColors();persist();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('beforeunload',persist);resize?.disconnect();interaction?.dispose();controls?.dispose();effects?.dispose();if(duck){pond.scene.remove(duck.root);duck.dispose();}pond?.dispose();renderer?.dispose();renderer?.domElement.remove();audio.dispose();});
</script>

<template>
<div class="app-shell"><header><a class="brand" href="#"><span class="brand-mark">≈</span><strong>SCAN3D<span> / LITTLE POND</span></strong></a><div class="header-note">真实外形，由你赋色</div><span class="local"><i></i> PC 本地 · 独立运行</span></header>
<main><aside class="intro"><span class="eyebrow">YOUR DUCK, YOUR PALETTE.</span><h1>给小鸭<br><em>一点颜色。</em></h1><p class="lead">保留扫描的形状，<br>配一身你喜欢的颜色。</p><div class="name-card"><label for="pet-name">今天也要好好相处</label><div><input id="pet-name" v-model="name" maxlength="16" aria-label="鸭子名字"><span>✎</span></div><small>点击名字，给它一个昵称</small></div>
<div class="stats"><div v-for="s in [{label:'心情',value:mood,color:'#d5a088'},{label:'精力',value:energy,color:'#87b5b1'}]" :key="s.label"><div class="stat-title"><span>{{s.label}}</span><b>{{s.value}}<small> / 100</small></b></div><div class="bar"><i :style="{width:s.value+'%',background:s.color}"></i></div></div></div><p class="fine">游戏状态 · 非扫描测量结果</p>
<div class="source-card"><span>REAL SHAPE / CUSTOM COLOR</span><strong>形状真实，颜色自选。</strong><p>2026.10.03 鸭子 STL 展示副本<br>原始扫描文件保持不变</p><button class="text-button" @click="details=!details">{{details?'收起说明 −':'分区方法与展示设置 ↗'}}</button></div></aside>
<section class="pond-panel"><div ref="host" class="viewport"></div><div class="scene-top"><span class="scene-pill"><i></i>{{editing?'上色中 · 动作暂停':labels[status]}}</span><span class="scene-number">STL / YOUR COLORS</span></div>
<div v-if="!ready&&!error" class="loading">正在加载 STL 几何…<small>不加载扫描 RGB 与点云</small></div><div v-if="error" class="loading error">{{error}}<button @click="retry">重新加载</button></div><div v-if="status==='sleep'&&!editing" class="zzz">z <span>z</span> Z</div><div class="bubble" role="status">{{message}}</div>
<div class="scene-toolbar"><div class="segmented"><button :class="{active:mode==='painted'}" @click="mode='painted'">自选上色</button><button :class="{active:mode==='stl'}" @click="mode='stl'">素色 STL</button></div><button @click="resetView" :disabled="!ready">↺ 视角</button><button @click="sound=!sound" :aria-pressed="sound">{{sound?'♪ 声音开':'♪ 静音'}}</button></div><div class="scene-footer"><span>{{editing?(tool==='brush'?'左键涂分区 · 右键旋转 · 滚轮缩放':'点击选区 · 拖动旋转 · 滚轮缩放'):(petMode?'在鸭子身上按住轻划':'点水面游动 · 点小鸭回应')}}</span><span>{{fps||'—'}} FPS</span></div>
<div v-if="details" class="details"><div class="details-head"><b>STL 表面分区 · 可手动修正</b><button @click="details=false" aria-label="关闭资产说明">×</button></div><p>展示 {{meta?.faces.toLocaleString()}} 个三角面。先用嘴、眼睛候选位置及头身几何先验确定种子，再沿相邻三角面连通生长。此版本是几何辅助分区，不是训练后的图像语义分割模型。</p><p>分区边界可能不准：用「修正画笔」将局部表面划入所选区域。画笔沿连通表面扩展，避免直接穿透到另一面。</p><p>不再显示点云和扫描 RGB。这里的颜色由你选择，不表示实物测量颜色。标准 STL 不携带颜色；导出 GLB 保存颜色，导出配置保存可编辑分区。</p><label>入水深度 <b>{{waterline}} mm</b><input type="range" min="2" max="10" step=".5" v-model.number="waterline" aria-label="入水深度"></label><label>朝向微调 <b>{{yaw}}°</b><input type="range" min="-180" max="180" step="5" v-model.number="yaw" aria-label="模型朝向微调"></label><p>资源读取 / 解码 {{loadMs}} ms · 当前 {{fps}} FPS</p><a href="/assets/duck-original-mm.stl" download>下载原始 STL 的副本 ↗</a></div>
</section>
<aside class="actions paint-panel"><div class="panel-tabs"><button :class="{active:editing}" @click="editing=true" :disabled="!ready">模型上色</button><button :class="{active:!editing}" @click="editing=false" :disabled="!ready">池塘互动</button></div>
<template v-if="editing"><h2>给它换个颜色</h2><p class="subtle">点选部位，整区上色。</p><div class="region-grid"><button v-for="(r,i) in regions" :key="r" :class="{selected:selected===i}" @click="selected=i" :disabled="!ready"><i :style="{background:palette[i]}"></i>{{r}}</button></div>
<div class="color-row"><input type="color" :value="palette[selected]" @input="setColor(($event.target as HTMLInputElement).value)" :aria-label="regions[selected]+'颜色'" :disabled="!ready"><div><b>{{regions[selected]}}</b><input v-model="hex" @input="onHexInput" @keyup.enter="setColor(hex)" aria-label="颜色十六进制" spellcheck="false" maxlength="7" :disabled="!ready"></div></div>
<div class="presets"><button @click="preset('cream')" :disabled="!ready">奶油</button><button @click="preset('pink')" :disabled="!ready">粉团</button><button @click="preset('white')" :disabled="!ready">暖白</button></div>
<div class="paint-tools"><div class="segmented"><button :class="{active:tool==='select'}" @click="tool='select'">点选区域</button><button :class="{active:tool==='brush'}" @click="tool='brush';mode='painted'">修正画笔</button></div><label v-if="tool==='brush'">表面半径 {{radius}} mm<input type="range" min=".8" max="7" step=".2" v-model.number="radius" aria-label="画笔半径"></label><label class="highlight"><input type="checkbox" v-model="highlight"> 高亮选中分区</label><div class="small-actions"><button @click="undo" :disabled="!undoCount">撤销修正</button><button @click="resetRegions" :disabled="!ready">恢复候选分区</button></div></div>
<button class="export-button" @click="exportGLB" :disabled="!ready||exporting">{{exporting?'导出中…':'导出彩色 GLB ↗'}}</button><div class="config-actions"><button @click="exportConfig" :disabled="!ready">导出配置</button><label>导入配置<input type="file" accept=".json" @change="importConfig" :disabled="!ready"></label></div><p class="save-status">{{saveStatus}}</p><p class="fine">STL 保留几何，GLB 保留自选颜色。<br>候选分区可以修正，原件不会被覆盖。</p></template>
<template v-else><h2>陪它一会儿</h2><p class="subtle">漂浮、摇摆，还有一点小开心。</p><button class="action-card" :class="{selected:petMode}" @click="petMode=!petMode" :disabled="!ready||status==='sleep'" :aria-pressed="petMode"><span class="action-icon">♡</span><span><b>{{petMode?'结束抚摸':'轻轻摸摸'}}</b><small>开启后，在小鸭身上轻划</small></span></button><button class="action-card" @click="act('celebrate')" :disabled="!ready||status==='sleep'"><span class="action-icon">✧</span><span><b>开心一下</b><small>轻轻跃起，落回水里</small></span></button><button class="sleep-button" @click="petMode=false;act(status==='sleep'?'wake':'sleep')" :disabled="!ready"><span>☾</span>{{status==='sleep'?'轻轻唤醒':'休息一下'}}</button><div class="note"><span>你的颜色，它的慢生活</span><p>原始外形不变，<br>不添加脚，不拉伸身体。</p></div></template>
</aside></main><footer><span>SCAN3D · 扫描实物的另一种可能</span><span>真实几何 · 自选配色 · 本地保存</span></footer></div>
</template>
